    var frame = d.querySelector('[data-name^="Screen/"]') || d.firstElementChild;
    var m = document.createElement('div');
    m.className = 'lsb-mount ls-popmount';
    m.setAttribute('data-name', "Popup/Charger Battery - Status");
    m.innerHTML = '<div class="lsb-root ls-pop">' + window.build_lsb(base) + '</div>';
    frame.appendChild(m);
    return d.innerHTML;
